<?php
header('Content-Type: application/json; charset=UTF-8');
if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once __DIR__.'/../config/database.php';
function categoryReply($ok,$message,$data=[],$code=200){http_response_code($code);echo json_encode(['status'=>$ok,'message'=>$message,'data'=>$data],JSON_UNESCAPED_UNICODE);exit;}
$sql="CREATE TABLE IF NOT EXISTS kategori_toko(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(80) NOT NULL UNIQUE,deskripsi VARCHAR(255) NULL,gambar_url VARCHAR(500) NULL,dibuat_pada TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4";if(!$conn->query($sql))categoryReply(false,'Kategori gagal disiapkan.',[],500);
$method=$_SERVER['REQUEST_METHOD'];$body=json_decode(file_get_contents('php://input'),true)?:[];$admin=($_SESSION['user']['peran']??'')==='admin';
if($method==='GET'){$rows=$conn->query('SELECT * FROM kategori_toko ORDER BY nama')->fetch_all(MYSQLI_ASSOC);categoryReply(true,'Daftar kategori.',['categories'=>$rows]);}
if(!$admin)categoryReply(false,'Hanya admin yang dapat mengelola kategori.',[],403);
if($method==='POST'&&($body['action']??'')==='save'){$id=(int)($body['id']??0);$name=trim($body['nama']??'');$desc=trim($body['deskripsi']??'');$image=trim($body['gambar_url']??'');if($name===''||mb_strlen($name)>80||mb_strlen($desc)>255)categoryReply(false,'Nama wajib diisi (maks. 80 karakter), deskripsi maksimal 255 karakter.',[],422);if($image!==''&&!filter_var($image,FILTER_VALIDATE_URL))categoryReply(false,'URL gambar kategori tidak valid.',[],422);$oldName='';if($id){$lookup=$conn->prepare('SELECT nama FROM kategori_toko WHERE id=?');$lookup->bind_param('i',$id);$lookup->execute();$oldName=$lookup->get_result()->fetch_assoc()['nama']??'';$stmt=$conn->prepare('UPDATE kategori_toko SET nama=?,deskripsi=?,gambar_url=? WHERE id=?');$stmt->bind_param('sssi',$name,$desc,$image,$id);}else{$stmt=$conn->prepare('INSERT INTO kategori_toko(nama,deskripsi,gambar_url) VALUES(?,?,?)');$stmt->bind_param('sss',$name,$desc,$image);}if(!$stmt->execute())categoryReply(false,$conn->errno===1062?'Nama kategori sudah digunakan.':'Kategori gagal disimpan.',[],409);if($oldName!==''&&$oldName!==$name){$rename=$conn->prepare('UPDATE produk SET kategori=? WHERE kategori=?');$rename->bind_param('ss',$name,$oldName);$rename->execute();}categoryReply(true,'Kategori disimpan.');}
if($method==='POST'&&($body['action']??'')==='delete'){$id=(int)($body['id']??0);$s=$conn->prepare('SELECT nama FROM kategori_toko WHERE id=?');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();if(!$row)categoryReply(false,'Kategori tidak ditemukan.',[],404);$s=$conn->prepare('SELECT COUNT(*) total FROM produk WHERE kategori=?');$s->bind_param('s',$row['nama']);$s->execute();if((int)$s->get_result()->fetch_assoc()['total']>0)categoryReply(false,'Kategori masih dipakai produk. Ubah kategori produk terlebih dahulu.',[],409);$s=$conn->prepare('DELETE FROM kategori_toko WHERE id=?');$s->bind_param('i',$id);$s->execute();categoryReply(true,'Kategori dihapus.');}
categoryReply(false,'Aksi tidak dikenal.',[],400);
